 242				sessionManager.newSession({ parentSession: options.parentSession });
 243			}
 244	
 245			await this.teardownCurrent("new", sessionManager.getSessionFile());
 246			this.apply(
 247				await this.createRuntime({
 248					cwd: this.cwd,
 249					agentDir: this.services.agentDir,
 250					sessionManager,
 251					sessionStartEvent: { type: "session_start", reason: "new", previousSessionFile },
 252				}),
 253			);
 254			if (options?.setup) {
 255				await options.setup(this.session.sessionManager);
 256				this.session.agent.state.messages = this.session.sessionManager.buildSessionContext().messages;
 257			}
 258			await this.finishSessionReplacement(options?.withSession);
 259			return { cancelled: false };
 260		}
