 354		/**
 355		 * Import a session JSONL file and switch runtime state to the imported session.
 356		 *
 357		 * @returns `{ cancelled: true }` when cancelled by `session_before_switch`, otherwise `{ cancelled: false }`.
 358		 * @throws {SessionImportFileNotFoundError} When the input path does not exist.
 359		 * @throws {MissingSessionCwdError} When the imported session cwd cannot be resolved and no override is provided.
 360		 */
 361		async importFromJsonl(inputPath: string, cwdOverride?: string): Promise<{ cancelled: boolean }> {
 362			const resolvedPath = resolvePath(inputPath);
 363			if (!existsSync(resolvedPath)) {
 364				throw new SessionImportFileNotFoundError(resolvedPath);
 365			}
 366	
 367			const sessionDir = this.session.sessionManager.getSessionDir();
 368			if (!existsSync(sessionDir)) {
 369				mkdirSync(sessionDir, { recursive: true });
 370			}
 371	
 372			const destinationPath = join(sessionDir, basename(resolvedPath));
 373			const beforeResult = await this.emitBeforeSwitch("resume", destinationPath);
 374			if (beforeResult.cancelled) {
 375				return beforeResult;
 376			}
 377	
 378			const previousSessionFile = this.session.sessionFile;
 379			if (resolve(destinationPath) !== resolvedPath) {
 380				copyFileSync(resolvedPath, destinationPath);
 381			}
 382	
 383			const sessionManager = SessionManager.open(destinationPath, sessionDir, cwdOverride);
 384			assertSessionCwdExists(sessionManager, this.cwd);
 385			await this.teardownCurrent("resume", sessionManager.getSessionFile());
 386			this.apply(
 387				await this.createRuntime({
 388					cwd: sessionManager.getCwd(),
 389					agentDir: this.services.agentDir,
 390					sessionManager,
 391					sessionStartEvent: { type: "session_start", reason: "resume", previousSessionFile },
 392				}),
 393			);
 394			await this.finishSessionReplacement();
 395			return { cancelled: false };
 396		}
