 617		// Track last assistant message for auto-compaction check
 618		private _lastAssistantMessage: AssistantMessage | undefined = undefined;
 619	
 620		/** Internal handler for agent events - shared by subscribe and reconnect */
 621		private _handleAgentEvent = async (event: AgentEvent): Promise<void> => {
 622			// When a user message starts, check if it's from either queue and remove it BEFORE emitting
 623			// This ensures the UI sees the updated queue state
 624			if (event.type === "message_start" && event.message.role === "user") {
 625				this._overflowRecoveryAttempted = false;
 626				const messageText = contentText(event.message.content, "");
 627				if (messageText) {
 628					// Check steering queue first
 629					const steeringIndex = this._steeringMessages.indexOf(messageText);
 630					if (steeringIndex !== -1) {
 631						this._steeringMessages.splice(steeringIndex, 1);
 632						this._emitQueueUpdate();
 633					} else {
 634						// Check follow-up queue
 635						const followUpIndex = this._followUpMessages.indexOf(messageText);
 636						if (followUpIndex !== -1) {
 637							this._followUpMessages.splice(followUpIndex, 1);
 638							this._emitQueueUpdate();
 639						}
 640					}
 641				}
 642			}
 643	
 644			// Emit to extensions first
 645			await this._emitExtensionEvent(event);
 646	
 647			// Notify all listeners
 648			this._emit(event.type === "agent_end" ? { ...event, willRetry: this._willRetryAfterAgentEnd(event) } : event);
 649	
 650			// Handle session persistence
 651			if (event.type === "message_end") {
 652				// Check if this is a custom message from extensions
 653				if (event.message.role === "custom") {
 654					// Persist as CustomMessageEntry
 655					this.sessionManager.appendCustomMessageEntry(
 656						event.message.customType,
 657						event.message.content,
 658						event.message.display,
 659						event.message.details,
 660					);
 661				} else if (
 662					event.message.role === "user" ||
 663					event.message.role === "assistant" ||
 664					event.message.role === "toolResult"
 665				) {
 666					// Regular LLM message - persist as SessionMessageEntry
 667					this.sessionManager.appendMessage(event.message);
 668				}
 669				// Other message types (bashExecution, compactionSummary, branchSummary) are persisted elsewhere
 670	
 671				// Track assistant message for auto-compaction (checked on agent_end)
 672				if (event.message.role === "assistant") {
 673					this._lastAssistantMessage = event.message;
 674	
 675					const assistantMsg = event.message as AssistantMessage;
 676					if (assistantMsg.stopReason !== "error" && assistantMsg.stopReason !== "length") {
 677						this._overflowRecoveryAttempted = false;
 678					}
 679	
 680					// Reset retry counter immediately on successful assistant response
 681					// This prevents accumulation across multiple LLM calls within a turn
 682					if (assistantMsg.stopReason !== "error" && this._retryAttempt > 0) {
 683						this._emit({
 684							type: "auto_retry_end",
 685							success: true,
 686							attempt: this._retryAttempt,
 687						});
 688						this._retryAttempt = 0;
 689					}
 690				}
 691			}
 692		};
 693	
 694		private _willRetryAfterAgentEnd(event: Extract<AgentEvent, { type: "agent_end" }>): boolean {
 695			const settings = this.settingsManager.getRetrySettings();
 696			if (!settings.enabled || this._retryAttempt >= settings.maxRetries) {
 697				return false;
 698			}
 699	
 700			for (let i = event.messages.length - 1; i >= 0; i--) {
 701				const message = event.messages[i];
 702				if (message.role === "assistant") {
 703					return this._isRetryableError(message as AssistantMessage);
 704				}
 705			}
 706			return false;
 707		}
 708	
 709		/** Find the last assistant message in agent state (including aborted ones) */
 710		private _findLastAssistantMessage(): AssistantMessage | undefined {
 711			const messages = this.agent.state.messages;
 712			for (let i = messages.length - 1; i >= 0; i--) {
 713				const msg = messages[i];
 714				if (msg.role === "assistant") {
 715					return msg as AssistantMessage;
 716				}
 717			}
 718			return undefined;
 719		}
 720	
 721		private _replaceMessageInPlace(target: AgentMessage, replacement: AgentMessage): void {
 722			// Agent-core stores the finalized message object in its state before emitting message_end.
 723			// SessionManager persistence happens later in _handleAgentEvent() with event.message.
 724			// Mutating this object in place keeps agent state, later turn/agent events, listeners,
 725			// and the eventual SessionManager.appendMessage(event.message) persistence in sync.
 726			if (target === replacement) {
 727				return;
 728			}
 729	
 730			const targetRecord = target as unknown as Record<string, unknown>;
 731			for (const key of Object.keys(targetRecord)) {
 732				delete targetRecord[key];
 733			}
 734			Object.assign(targetRecord, replacement);
 735		}
