 737		/** Emit extension events based on agent events */
 738		private async _emitExtensionEvent(event: AgentEvent): Promise<void> {
 739			if (event.type === "agent_start") {
 740				this._turnIndex = 0;
 741				await this._extensionRunner.emit({ type: "agent_start" });
 742			} else if (event.type === "agent_end") {
 743				await this._extensionRunner.emit({ type: "agent_end", messages: event.messages });
 744			} else if (event.type === "turn_start") {
 745				const extensionEvent: TurnStartEvent = {
 746					type: "turn_start",
 747					turnIndex: this._turnIndex,
 748					timestamp: Date.now(),
 749				};
 750				await this._extensionRunner.emit(extensionEvent);
 751			} else if (event.type === "turn_end") {
 752				const extensionEvent: TurnEndEvent = {
 753					type: "turn_end",
 754					turnIndex: this._turnIndex,
 755					message: event.message,
 756					toolResults: event.toolResults,
 757				};
 758				await this._extensionRunner.emit(extensionEvent);
 759				this._turnIndex++;
 760			} else if (event.type === "message_start") {
 761				const extensionEvent: MessageStartEvent = {
 762					type: "message_start",
 763					message: event.message,
 764				};
 765				await this._extensionRunner.emit(extensionEvent);
 766			} else if (event.type === "message_update") {
 767				const extensionEvent: MessageUpdateEvent = {
 768					type: "message_update",
 769					message: event.message,
 770					assistantMessageEvent: event.assistantMessageEvent,
 771				};
 772				await this._extensionRunner.emit(extensionEvent);
 773			} else if (event.type === "message_end") {
 774				const extensionEvent: MessageEndEvent = {
 775					type: "message_end",
 776					message: event.message,
 777				};
 778				const replacement = await this._extensionRunner.emitMessageEnd(extensionEvent);
 779				if (replacement) {
 780					// Untyped extension handlers can return messages with null/missing content;
 781					// normalize so it never enters agent state or session history.
 782					const normalized =
 783						(replacement.role === "user" ||
 784							replacement.role === "assistant" ||
 785							replacement.role === "toolResult" ||
 786							replacement.role === "custom") &&
 787						replacement.content == null
 788							? ({ ...replacement, content: [] } as AgentMessage)
 789							: replacement;
 790					this._replaceMessageInPlace(event.message, normalized);
 791				}
 792			} else if (event.type === "tool_execution_start") {
 793				const extensionEvent: ToolExecutionStartEvent = {
 794					type: "tool_execution_start",
 795					toolCallId: event.toolCallId,
 796					toolName: event.toolName,
 797					args: event.args,
 798				};
 799				await this._extensionRunner.emit(extensionEvent);
 800			} else if (event.type === "tool_execution_update") {
1060				contextFiles: loadedContextFiles,
1061				customPrompt: loaderSystemPrompt,
1062				appendSystemPrompt,
1063				selectedTools: validToolNames,
1064				toolSnippets,
1065				promptGuidelines,
1066			};
1067			return buildSystemPrompt(this._baseSystemPromptOptions);
1068		}
