1074		private async _runAgentPrompt(messages: AgentMessage | AgentMessage[]): Promise<void> {
1075			this._isAgentRunActive = true;
1076			try {
1077				await this.agent.prompt(messages);
1078				while (await this._handlePostAgentRun()) {
1079					await this.agent.continue();
1080				}
1081			} finally {
1082				this._systemPromptOverride = undefined;
1083				this._flushPendingBashMessages();
1084				await this._emitAgentSettled();
1085			}
1086		}
1087	
1088		private async _handlePostAgentRun(): Promise<boolean> {
1089			const msg = this._lastAssistantMessage;
1090			this._lastAssistantMessage = undefined;
1091			if (!msg) {
1092				return false;
1093			}
1094	
1095			if (this._isRetryableError(msg) && (await this._prepareRetry(msg))) {
1096				return true;
1097			}
1098	
1099			if (msg.stopReason === "error" && this._retryAttempt > 0) {
1100				this._emit({
1101					type: "auto_retry_end",
1102					success: false,
1103					attempt: this._retryAttempt,
1104					finalError: msg.errorMessage,
1105				});
1106				this._retryAttempt = 0;
1107			}
1108	
1109			if (await this._checkCompaction(msg)) {
1110				return true;
1111			}
1112	
1113			// The agent loop drains both queues before emitting agent_end. Any messages
1114			// here were queued by agent_end extension handlers and need a continuation.
1115			return this.agent.hasQueuedMessages();
1116		}
