1118		/**
1119		 * Send a prompt to the agent.
1120		 * - Handles extension commands (registered via pi.registerCommand) immediately, even during streaming
1121		 * - Expands file-based prompt templates by default
1122		 * - During streaming, queues via steer() or followUp() based on streamingBehavior option
1123		 * - Validates model and API key before sending (when not streaming)
1124		 * @throws Error if streaming and no streamingBehavior specified
1125		 * @throws Error if no model selected or no API key available (when not streaming)
1126		 */
1127		async prompt(text: string, options?: PromptOptions): Promise<void> {
1128			const expandPromptTemplates = options?.expandPromptTemplates ?? true;
1129			const preflightResult = options?.preflightResult;
1130			let messages: AgentMessage[] | undefined;
1131	
1132			try {
1133				// Handle extension commands first (execute immediately, even during streaming)
1134				// Extension commands manage their own LLM interaction via pi.sendMessage()
1135				if (expandPromptTemplates && text.startsWith("/")) {
2285				if (this._extensionRunner && savedCompactionEntry) {
2286					await this._extensionRunner.emit({
2287						type: "session_compact",
2288						compactionEntry: savedCompactionEntry,
2289						fromExtension,
2290						reason,
2291						willRetry,
2292					});
2293				}
2294	
2295				const result: CompactionResult = {
2296					summary,
2297					firstKeptEntryId,
2298					tokensBefore,
2299					estimatedTokensAfter,
2300					usage,
2301					details,
2302				};
2303				this._emit({ type: "compaction_end", reason, result, aborted: false, willRetry });
2304	
2305				if (willRetry) {
2306					const messages = this.agent.state.messages;
2307					const lastMsg = messages[messages.length - 1];
2308					// The overflow response was persisted on message_end before _checkCompaction() removed it
2309					// from agent state. Rebuilding state from the new compaction can restore that kept entry,
2310					// leaving an assistant as the final message. agent.continue() rejects that state, so remove
2311					// the retriable error or truncated-length response again before continuing the interrupted turn.
2312					if (lastMsg?.role === "assistant" && (lastMsg.stopReason === "error" || lastMsg.stopReason === "length")) {
2313						this.agent.state.messages = messages.slice(0, -1);
2314					}
2315					return true;
2316				}
2317	
2318				// Auto-compaction can complete while follow-up/steering/custom messages are waiting.
2319				// Continue once so queued messages are delivered.
2320				return this.agent.hasQueuedMessages();
2321			} catch (error) {
2322				const errorMessage = error instanceof Error ? error.message : "compaction failed";
2323				if (started) {
2324					const formattedErrorMessage =
2325						reason === "overflow"
2326							? `Context overflow recovery failed: ${errorMessage}`
2327							: `Auto-compaction failed: ${errorMessage}`;
2328					this._emit({
2329						type: "compaction_end",
2330						reason,
2331						result: undefined,
2332						aborted: false,
2333						willRetry: false,
2334						errorMessage: formattedErrorMessage,
2335					});
2336					await this._emitSessionCompactFailed({
2337						reason,
2338						errorMessage: formattedErrorMessage,
2339						aborted: false,
2340						willRetry: false,
2341						fromExtension,
2342					});
2343				}
2344				return false;
2345			} finally {
2720				this._extensionRunnerRef.current = this._extensionRunner;
2721			}
2722			this._bindExtensionCore(this._extensionRunner);
2723			this._applyExtensionBindings(this._extensionRunner);
2724	
2725			const defaultActiveToolNames = this._baseToolsOverride
2726				? Object.keys(this._baseToolsOverride)
2727				: ["read", "bash", "edit", "write"];
2728			const baseActiveToolNames = options.activeToolNames ?? defaultActiveToolNames;
2729			this._refreshToolRegistry({
2730				activeToolNames: baseActiveToolNames,
2731				includeAllExtensionTools: options.includeAllExtensionTools,
2732			});
2733		}
