2735		async reload(options?: { beforeSessionStart?: () => void | Promise<void> }): Promise<void> {
2736			const oldRunner = this._extensionRunner;
2737			const previousFlagValues = oldRunner.getFlagValues();
2738			await emitSessionShutdownEvent(oldRunner, { type: "session_shutdown", reason: "reload" });
2739			oldRunner.invalidate();
2740			await this.settingsManager.reload();
2741			this.syncQueueModesFromSettings();
2742			resetApiProviders();
2743			await this._resourceLoader.reload();
2744			this._buildRuntime({
2745				activeToolNames: this.getActiveToolNames(),
2746				flagValues: previousFlagValues,
2747				includeAllExtensionTools: true,
2748			});
2749	
2750			const hasBindings =
2751				this._extensionUIContext ||
2752				this._extensionCommandContextActions ||
2753				this._extensionShutdownHandler ||
2754				this._extensionErrorListener;
2755			if (hasBindings) {
2756				await options?.beforeSessionStart?.();
2757				await this._extensionRunner.emit({ type: "session_start", reason: "reload" });
2758				await this.extendResourcesFromExtensions("reload");
2759			}
2760		}
