const root = mkdtempSync(join(tmpdir(), 'pi-jsonl-live-'));
const sessionDir = join(root, 'sessions');
const cwd = join(root, 'cwd');
mkdirSync(cwd);
const result = { root, platform: process.platform, node: process.version };
try {
  const sm = SessionManager.create(cwd, sessionDir, { id: 'exp-birth' });
  const file = sm.getSessionFile();
  result.path = file;
  result.afterCreate = { exists: existsSync(file), id: sm.getSessionId(), dir: sm.getSessionDir() };
  sm.appendMessage({ role: 'user', content: 'hello', timestamp: Date.now() });
  result.afterUser = { exists: existsSync(file) };
  sm.appendMessage({ role: 'assistant', content: [{ type: 'text', text: 'ok' }], api: 'test', provider: 'test', model: 'test', usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } }, stopReason: 'stop', timestamp: Date.now() });
  const raw = readFileSync(file, 'utf8');
  result.afterAssistant = { exists: true, endsNewline: raw.endsWith('\n'), roles: raw.trimEnd().split('\n').map(line => JSON.parse(line).message?.role ?? JSON.parse(line).type), parsedEntries: loadEntriesFromFile(file).length };

  const truncated = join(sessionDir, 'truncated.jsonl');
  appendFileSync(truncated, raw + '{"type":"message"');
  result.truncatedTail = { parsedEntries: loadEntriesFromFile(truncated).length, physicalBytes: readFileSync(truncated).length };
  const validNoNewline = join(sessionDir, 'valid-no-newline.jsonl');
  appendFileSync(validNoNewline, raw.trimEnd());
  result.validNoNewline = { parsedEntries: loadEntriesFromFile(validNoNewline).length };

  const fileEvents = [];
  const dirEvents = [];
  const fw = watch(file, (event, name) => fileEvents.push([event, name]));
  const dw = watch(sessionDir, (event, name) => dirEvents.push([event, name]));
  const sm2 = SessionManager.create(cwd, sessionDir, { id: 'exp-switch' });
  sm2.appendMessage({ role: 'user', content: 'new', timestamp: Date.now() });
  sm2.appendMessage({ role: 'assistant', content: [{ type: 'text', text: 'new ok' }], api: 'test', provider: 'test', model: 'test', usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } }, stopReason: 'stop', timestamp: Date.now() });
